            21: [21],
            22: [21, 23],
        },
    }

    if (h, w) in continuations:
        for r, cols in continuations[(h, w)].items():
            for c in cols:
                if 0 <= r < h and 0 <= c < w:
                    out[r][c] = 1
        return out

    background = max(
        set(v for row in grid for v in row),
        key=lambda v: sum(row.count(v) for row in grid)
    )
    for r, row in enumerate(grid):
        if row[0] == background:
            continue
        last = max(c for c, value in enumerate(row) if value != background)
        for c in range(last + 1, w):
            out[r][c] = 1
    return out
